/// Caps each element of `a` to at most 2 (in place), then returns the sum.
/// 
/// Assumptions per problem statement:
/// - `N` equals the initial length of `a`
/// - `N <= 0x7FFF_FFFF`
/// - After capping, the sum is <= 2 * N
pub fn myfun(a: &mut Vec<u32>, n: u32) -> u32 {
    debug_assert_eq!(a.len(), n as usize);

    let mut sum: u32 = 0;

    for x in a.iter_mut() {
        if *x > 2 {
            *x = 2;
        }
        sum = sum.wrapping_add(*x);
    }

    // With the given guarantees, this should not overflow and should satisfy sum <= 2*n.
    debug_assert!(sum <= n.saturating_mul(2));

    sum
}